BEGIN;

-- Run after the in-house analytics, history-extension, and pause/resume migrations.
-- Answer keys are accessed only by the authenticated diagnostic Edge Function.
CREATE TABLE IF NOT EXISTS public.in_house_diagnostic_item_keys (
  bank_scope text NOT NULL CHECK (bank_scope IN ('diagnostic', 'remediation')),
  item_id text NOT NULL,
  item_source text NOT NULL,
  parent_item_id text,
  selectable boolean NOT NULL DEFAULT true,
  item_type text NOT NULL,
  difficulty integer CHECK (difficulty BETWEEN 1 AND 3),
  blueprint text,
  category text,
  nclex_category text,
  topic text,
  cognitive_level text,
  core_tags jsonb NOT NULL DEFAULT '[]'::jsonb,
  correct_response jsonb,
  rationale jsonb,
  sequence_order integer,
  case_length integer,
  PRIMARY KEY (bank_scope, item_id),
  CHECK (jsonb_typeof(core_tags) = 'array'),
  CHECK (case_length IS NULL OR case_length > 0)
);

ALTER TABLE public.in_house_diagnostic_item_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.in_house_diagnostic_item_keys FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.in_house_diagnostic_item_keys TO service_role;

CREATE INDEX IF NOT EXISTS idx_in_house_diagnostic_keys_selection
  ON public.in_house_diagnostic_item_keys(bank_scope, selectable, nclex_category, difficulty);

INSERT INTO public.in_house_diagnostic_item_keys (
  bank_scope, item_id, item_source, parent_item_id, selectable, item_type,
  difficulty, blueprint, category, nclex_category, topic, cognitive_level,
  core_tags, correct_response, rationale, sequence_order, case_length
) VALUES
  ('diagnostic', 'm1', 'existing-original-bank', NULL, true, 'mcq', 1, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '["delegation"]'::jsonb, '[1]'::jsonb, '{"correct":"Ambulating a stable post-op day 2 client is a routine task requiring no clinical judgment — appropriate for UAP.","wrong":["Assessing breath sounds requires clinical interpretation — RN only.","Client education requires nursing judgment — not delegable to UAP.","Telemetry interpretation requires clinical judgment — RN only."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'm2', 'existing-original-bank', NULL, true, 'mcq', 2, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '["delegation"]'::jsonb, '[2]'::jsonb, '{"correct":"Assessment is the nurse''s clinical interpretation of what is happening — the ''A'' in SBAR.","wrong":["Situation describes what is happening right now (the problem statement).","Background provides relevant clinical history.","Recommendation is the nurse''s request for action."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'm3', 'existing-original-bank', NULL, true, 'mcq', 2, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Client safety is the immediate priority — the charge nurse must intervene to correct the technique before harm occurs.","wrong":["Delaying until a staff meeting leaves the client at risk for infection.","An incident report may be completed later, but immediate client safety comes first.","Asking the client is inappropriate and does not address the safety concern."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'm4', 'existing-original-bank', NULL, true, 'mcq', 3, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[0]'::jsonb, '{"correct":"The stable COPD client on 2L O2 is the most predictable assignment — appropriate for an agency nurse unfamiliar with the unit''s protocols.","wrong":["A new chest pain admission requires assessment by a nurse familiar with the unit''s cardiac protocols.","A post-op CABG day 1 client has high acuity and complex needs — not appropriate for an agency nurse.","A client on an insulin drip requires close titration and familiarity with unit protocols."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'm5', 'existing-original-bank', NULL, true, 'mcq', 2, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Client confidentiality is a legal and ethical right — the nurse must protect this information unless legally required to disclose.","wrong":["Overriding the client''s wishes violates HIPAA and patient rights.","Emergency contact notification does not apply here and is not legally required for HIV status.","Encouraging disclosure is appropriate over time, but the immediate response must affirm confidentiality."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'm6', 'existing-original-bank', NULL, true, 'sata', 2, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[0,2,3,5]'::jsonb, '{"correct":"The surgical time-out (Universal Protocol) requires verification of client identity, correct site/side, procedure type, and positioning.","wrong":["Insurance information is not part of the surgical time-out safety protocol.","Surgeon board certification is credentialed during privileging, not the time-out."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'si1', 'existing-original-bank', NULL, true, 'mcq', 1, 'Safe & Effective Care Environment', 'Safety & Infection Prevention', 'Safety & Infection Prevention', NULL, NULL, '["infection_prevention"]'::jsonb, '[2]'::jsonb, '{"correct":"TB is transmitted via airborne droplet nuclei (<5 microns) — airborne precautions with a negative-pressure room and N95 respirator are required.","wrong":["Contact precautions are for direct-contact organisms like MRSA or C. diff.","Droplet precautions are for larger respiratory droplets (influenza, pertussis) — not TB.","Reverse isolation protects immunocompromised clients from the environment."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'si2', 'existing-original-bank', NULL, true, 'mcq', 2, 'Safe & Effective Care Environment', 'Safety & Infection Prevention', 'Safety & Infection Prevention', NULL, NULL, '["infection_prevention"]'::jsonb, '[2]'::jsonb, '{"correct":"Once a sterile field is contaminated, the entire setup must be discarded and a new sterile kit obtained.","wrong":["The sterile drape is the border of the sterile field — contamination of it compromises the entire setup.","Documentation without replacing the kit does not restore sterility.","Alcohol wipes do not re-sterilize a contaminated sterile field."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'si3', 'existing-original-bank', NULL, true, 'mcq', 1, 'Safe & Effective Care Environment', 'Safety & Infection Prevention', 'Safety & Infection Prevention', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"C. diff spores are NOT killed by alcohol-based hand rubs — soap and water is required to physically remove the spores.","wrong":["Alcohol-based hand rubs are ineffective against C. diff spores.","Chlorhexidine wipes do not adequately remove C. diff spores.","They are not equally effective — alcohol rubs fail against C. diff."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'si4', 'existing-original-bank', NULL, true, 'mcq', 2, 'Safe & Effective Care Environment', 'Safety & Infection Prevention', 'Safety & Infection Prevention', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"MRSA is transmitted by direct or indirect contact — contact precautions (gown and gloves) are required.","wrong":["TB requires airborne precautions.","Influenza requires droplet precautions.","Meningococcal meningitis requires droplet precautions."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'hp1', 'existing-original-bank', NULL, true, 'mcq', 1, 'Health Promotion & Maintenance', 'Health Promotion', 'Health Promotion & Maintenance', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"No amount of alcohol is safe in pregnancy — any consumption risks fetal alcohol spectrum disorder.","wrong":["Daily prenatal vitamins are correct — no teaching needed.","Reporting decreased fetal movement after 28 weeks shows correct understanding.","Avoiding raw sushi is correct due to listeria and mercury risk."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'hp2', 'existing-original-bank', NULL, true, 'mcq', 1, 'Health Promotion & Maintenance', 'Health Screening', 'Health Promotion & Maintenance', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"The American Cancer Society recommends colorectal cancer screening beginning at age 45 for average-risk individuals.","wrong":["Colonoscopy is recommended every 10 years (not 5) for average-risk individuals.","Multiple screening modalities are acceptable — annual FOBT is just one option.","Screening is preventive — waiting for symptoms defeats its purpose."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'hp3', 'existing-original-bank', NULL, true, 'mcq', 2, 'Health Promotion & Maintenance', 'Developmental Stages', 'Health Promotion & Maintenance', NULL, NULL, '["pediatrics"]'::jsonb, '[3]'::jsonb, '{"correct":"Responding to one''s name is a milestone expected by 9–12 months. Failure at 15 months is a red flag for autism spectrum disorder or hearing loss.","wrong":["5–10 words at 15 months is appropriate — milestone is at least 1 word by 12 months.","Independent walking at 15 months is normal — milestone is by 15 months.","Using a spoon independently is typically mastered between 15–18 months."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'hp4', 'existing-original-bank', NULL, true, 'mcq', 2, 'Health Promotion & Maintenance', 'Health Promotion', 'Health Promotion & Maintenance', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Fresh grilled salmon with steamed vegetables and whole grains is naturally low in sodium — an appropriate choice.","wrong":["Canned soups are very high in sodium — often 800–1200 mg per serving.","Deli meats are heavily processed and high in sodium.","Canned fruits are often packed in syrups and may contain added sodium."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'hp5', 'existing-original-bank', NULL, true, 'sata', 2, 'Health Promotion & Maintenance', 'Health Promotion', 'Health Promotion & Maintenance', NULL, NULL, '[]'::jsonb, '[0,2,4,5]'::jsonb, '{"correct":"Hypertension, smoking, sedentary lifestyle, and hyperlipidemia are all modifiable through lifestyle changes and/or medications.","wrong":["Family history is a non-modifiable risk factor — it cannot be changed.","Age is a non-modifiable risk factor."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'hp6', 'existing-original-bank', NULL, true, 'mcq', 3, 'Health Promotion & Maintenance', 'Ante/Intra/Postpartum', 'Health Promotion & Maintenance', NULL, NULL, '["maternal_newborn"]'::jsonb, '[1]'::jsonb, '{"correct":"Painless bright red vaginal bleeding in the third trimester is the classic presentation of placenta previa — the placenta covers the cervical os.","wrong":["Abruptio placentae typically presents with painful, dark bleeding and uterine rigidity.","Preterm labor presents with contractions — not painless bleeding.","Ectopic pregnancy rupture occurs in the first trimester, not at 36 weeks."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ps1', 'existing-original-bank', NULL, true, 'mcq', 2, 'Psychosocial Integrity', 'Coping & Adaptation', 'Psychosocial Integrity', NULL, NULL, '["psych_safety"]'::jsonb, '[1]'::jsonb, '{"correct":"Reflecting the client''s emotional experience demonstrates therapeutic communication and acknowledges feelings without dismissing or redirecting.","wrong":["Minimizing feelings is non-therapeutic.","Focusing on education ignores the emotional state — teaching is ineffective during denial.","Consulting the educator is appropriate later, but the immediate priority is acknowledging feelings."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ps2', 'existing-original-bank', NULL, true, 'mcq', 2, 'Psychosocial Integrity', 'Mental Health Concepts', 'Psychosocial Integrity', NULL, NULL, '["psych_safety"]'::jsonb, '[2]'::jsonb, '{"correct":"Objective documentation uses the client''s exact words in quotes — it avoids interpretation and is legally defensible.","wrong":["While ''delusion of reference'' is clinically accurate, quoting the client is more objective and appropriate.","Labeling the client as ''delusional and psychotic'' is judgmental and not objective documentation.","The described phenomenon is a delusion (false fixed belief), not a hallucination (false sensory perception)."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ps3', 'existing-original-bank', NULL, true, 'mcq', 3, 'Psychosocial Integrity', 'Crisis Intervention', 'Psychosocial Integrity', NULL, NULL, '["psych_safety"]'::jsonb, '[2]'::jsonb, '{"correct":"This is an imminent safety emergency — the caller has means, plan, and intent. The priority is immediate emergency services while maintaining connection.","wrong":["Assessing support systems is not the priority when there is imminent danger.","Exploring history delays immediate life-saving action.","Scheduling follow-up is entirely inappropriate for an active suicidal emergency."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ps4', 'existing-original-bank', NULL, true, 'mcq', 2, 'Psychosocial Integrity', 'Therapeutic Communication', 'Psychosocial Integrity', NULL, NULL, '["psych_safety"]'::jsonb, '[2]'::jsonb, '{"correct":"This response acknowledges the client''s pain and invites them to share more — it is empathetic and open-ended.","wrong":["Telling a grieving person it ''will get easier'' minimizes their immediate pain.","Redirecting to a counselor, while potentially appropriate, blocks the therapeutic communication opportunity.","Telling a 3-day widow to ''move forward'' is dismissive and inappropriate."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ps5', 'existing-original-bank', NULL, true, 'mcq', 2, 'Psychosocial Integrity', 'Mental Health Concepts', 'Psychosocial Integrity', NULL, NULL, '["psych_safety"]'::jsonb, '[1]'::jsonb, '{"correct":"Physiological stability is the priority — severe malnutrition causes life-threatening electrolyte imbalances (especially hypokalemia) that must be corrected first.","wrong":["Therapeutic communication is important but secondary to physiological stabilization.","Refeeding must be done carefully to avoid refeeding syndrome — not immediately.","Dietary consult is appropriate but not the first priority."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ps6', 'existing-original-bank', NULL, true, 'sata', 2, 'Psychosocial Integrity', 'Therapeutic Communication', 'Psychosocial Integrity', NULL, NULL, '["psych_safety"]'::jsonb, '[0,2,3,5]'::jsonb, '{"correct":"Shuffling gait/rigidity (pseudoparkinsonism), tardive dyskinesia (tongue/facial movements), akathisia (restlessness), and acute dystonia (muscle contractions) are all EPS.","wrong":["Weight gain is a metabolic side effect of antipsychotics, not EPS.","Dry mouth and urinary retention are anticholinergic effects, not EPS."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'bc1', 'existing-original-bank', NULL, true, 'mcq', 1, 'Physiological Integrity', 'Basic Care & Comfort', 'Basic Care & Comfort', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Non-pharmacological comfort measures (repositioning, distraction) can be used now, while preparing to administer the scheduled analgesic on time — this is the most comprehensive response.","wrong":["Telling a client in pain to simply ''wait'' is inadequate nursing care.","One report of pain at 7/10 doesn''t immediately indicate regimen failure — first optimize current orders.","A PRN dose request is appropriate if the scheduled analgesic was just given — here, maximizing current orders is the priority."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'bc2', 'existing-original-bank', NULL, true, 'mcq', 1, 'Physiological Integrity', 'Basic Care & Comfort', 'Basic Care & Comfort', NULL, NULL, '["postoperative_risk"]'::jsonb, '[2]'::jsonb, '{"correct":"Elevating the head of bed 30–45 degrees uses gravity to keep gastric contents from refluxing into the airway — the primary prevention for aspiration during tube feeding.","wrong":["Flat positioning greatly increases aspiration risk.","Auscultation of air is no longer considered a reliable method of confirming tube placement.","Flushing maintains tube patency but does not prevent aspiration."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'bc3', 'existing-original-bank', NULL, true, 'sata', 2, 'Physiological Integrity', 'Basic Care & Comfort', 'Basic Care & Comfort', NULL, NULL, '[]'::jsonb, '[0,2,3,4]'::jsonb, '{"correct":"A spare tube for emergencies, properly secured ties, humidification to prevent secretion crusting, and regular inner cannula changes all maintain airway safety.","wrong":["Suctioning should be based on clinical assessment — not on a fixed schedule.","Trendelenburg is contraindicated; semi-Fowler''s or upright positioning is correct."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'bc4', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Basic Care & Comfort', 'Basic Care & Comfort', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Repositioning every 2 hours relieves pressure — the underlying cause of the injury. Offloading pressure is the priority intervention.","wrong":["Moisture barrier cream protects surrounding skin but does not address the cause of the injury.","Povidone-iodine is cytotoxic and destroys granulation tissue — contraindicated in wound care.","Donut rings concentrate pressure around the wound edges — actually worsen tissue damage."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph1', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '["insulin_glucose"]'::jsonb, '[2]'::jsonb, '{"correct":"Therapeutic aPTT is 60–100 seconds. At 180 seconds the client is supratherapeutic with high hemorrhage risk — hold and notify.","wrong":["Continuing a supratherapeutic infusion risks life-threatening bleeding.","Increasing the rate compounds the risk.","Protamine sulfate requires a provider order."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph2', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '["high_alert_medications"]'::jsonb, '[2]'::jsonb, '{"correct":"Therapeutic digoxin is 0.5–2.0 ng/mL. A level of 2.4 ng/mL is toxic — hold and notify.","wrong":["Potassium 4.2 is normal (3.5–5.0).","Sodium 138 is normal (136–145).","BUN 18 is normal (7–20)."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph3', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '["high_alert_medications"]'::jsonb, '[1]'::jsonb, '{"correct":"Diarrhea causes sodium and fluid loss, which raises lithium levels. Tremors are a sign of toxicity. This client needs immediate lithium level assessment.","wrong":["Adequate hydration helps maintain stable lithium levels — appropriate behavior.","Taking lithium with food to reduce GI side effects is a correct strategy.","A level of 0.9 mEq/L is within the therapeutic range of 0.6–1.2 mEq/L."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph4', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '["high_alert_medications"]'::jsonb, '[2]'::jsonb, '{"correct":"This is Red Man Syndrome — a rate-related reaction to vancomycin, not a true allergy. Slowing the infusion rate typically resolves the reaction.","wrong":["Diphenhydramine may be used as adjunct treatment but slowing the rate is the first intervention.","Red Man Syndrome is not anaphylaxis — it is a rate-related infusion reaction.","The IV line does not need to be discontinued — slowing the rate resolves the reaction."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph5', 'existing-original-bank', NULL, true, 'sata', 2, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '[]'::jsonb, '[0,2,3,4]'::jsonb, '{"correct":"Two-nurse verification, baseline vitals, 18G or larger catheter, and two-identifier client verification are all required before blood transfusion.","wrong":["Blood must be primed with 0.9% normal saline only — D5W causes hemolysis.","Blood must be infused slowly for the first 15 minutes to monitor for transfusion reactions."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph6', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Metformin must be held before and after iodinated contrast due to the risk of contrast-induced nephropathy leading to lactic acidosis.","wrong":["Administering metformin before contrast is contraindicated due to lactic acidosis risk.","Giving half the dose does not adequately reduce the risk.","History of prior contrast use does not eliminate the contraindication with metformin."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph7', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"A respiratory rate of 8 and unresponsiveness indicate opioid-induced respiratory depression — a medical emergency requiring naloxone administration immediately.","wrong":["Oxygen alone does not reverse opioid-induced respiratory depression.","Stimulation is insufficient for significant respiratory depression.","Documenting and waiting 15 minutes is dangerous — this is an emergency."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'ph8', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Pharmacological & Parenteral Therapies', 'Pharmacological & Parenteral Therapies', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"NSAIDs like ibuprofen increase bleeding risk when combined with warfarin by inhibiting platelet aggregation — clients should use acetaminophen instead.","wrong":["Regular INR monitoring is required to ensure therapeutic anticoagulation.","Consistent vitamin K intake (from leafy greens) is important for stable INR.","Reporting unusual bleeding is essential client education for warfarin."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'rr1', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Reduction of Risk Potential', 'Reduction of Risk Potential', NULL, NULL, '["fluids_electrolytes"]'::jsonb, '[0]'::jsonb, '{"correct":"Coolness, pallor, swelling, and slowed infusion are classic findings of IV infiltration. Stop the infusion and follow facility protocol.","wrong":["Phlebitis usually causes warmth, redness, and tenderness along the vein.","Extravasation involves a vesicant medication and requires specific antidote and protocol considerations.","Local infection commonly produces redness, warmth, drainage, or fever rather than cool pallor."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'rr2', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Reduction of Risk Potential', 'Reduction of Risk Potential', NULL, NULL, '["fluids_electrolytes"]'::jsonb, '[1]'::jsonb, '{"correct":"Tingling around the mouth and stridor post-thyroidectomy indicate hypocalcemia from accidental parathyroid removal, causing tetany and laryngospasm.","wrong":["Thyroid storm presents with hyperthermia, tachycardia, and hypertension — not these findings.","Infection is not an immediate post-op complication causing these neurological signs.","Laryngeal nerve damage alone causes hoarseness — not perioral tingling or stridor from tetany."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'rr3', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Reduction of Risk Potential', 'Reduction of Risk Potential', NULL, NULL, '["postoperative_risk"]'::jsonb, '[1]'::jsonb, '{"correct":"This is a classic post-lumbar puncture headache caused by CSF leakage. Lying flat reduces the pressure gradient, and increased fluids help replenish CSF volume.","wrong":["Acetaminophen alone without positional changes is insufficient for post-LP headache.","A post-LP headache is expected and does not indicate spinal cord injury.","Sitting up (high-Fowler''s) worsens the headache — the client should remain flat."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'rr4', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Reduction of Risk Potential', 'Reduction of Risk Potential', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '{"correct":"Hyperkalemia is a life-threatening complication of CKD because impaired kidneys cannot excrete potassium — it can cause fatal dysrhythmias.","wrong":["Albumin is monitored for nutrition but is not the most critical in CKD.","Calcium is important in CKD but hyperkalemia poses the most immediate life threat.","HbA1C is relevant if diabetes is the cause of CKD but is not the most critical CKD lab."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'rr5', 'existing-original-bank', NULL, true, 'sata', 3, 'Physiological Integrity', 'Reduction of Risk Potential', 'Reduction of Risk Potential', NULL, NULL, '[]'::jsonb, '[1,2,5]'::jsonb, '{"correct":"Calf pain/warmth suggests DVT. Urine output of 20 mL/hr is oliguria (normal is ≥30 mL/hr). Uncontrolled pain 30 min after IV analgesic needs reassessment.","wrong":["Temp 37.4°C (99.3°F) is normal — mild elevation is expected post-op.","Capillary refill of 2 seconds is normal.","Serosanguineous drainage is expected in early post-op wound healing."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa1', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '["airway_breathing"]'::jsonb, '[1]'::jsonb, '{"correct":"pH <7.35 = acidosis. Elevated PaCO2 (>45) = respiratory cause. HCO3 is normal (22–26) = no compensation yet. This is respiratory acidosis, uncompensated.","wrong":["Metabolic acidosis would show low HCO3, not elevated CO2 as the primary abnormality.","Respiratory alkalosis would show elevated pH and low CO2.","Metabolic alkalosis would show elevated pH and HCO3."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa2', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '["circulation_shock"]'::jsonb, '[2]'::jsonb, '{"correct":"Positioning and oxygenation address the immediate symptom of dyspnea first — then pharmacological intervention follows.","wrong":["Reweighing delays treatment of active respiratory distress.","Furosemide is indicated but the immediate priority is alleviating respiratory distress.","Fluid restriction is appropriate but not the priority when the client is actively dyspneic."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa3', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '["circulation_shock"]'::jsonb, '[1]'::jsonb, '{"correct":"Adequate urine output (0.5–1 mL/kg/hr in burn patients) signals adequate resuscitation. 15 mL/hr is inadequate — increase fluids per Parkland formula and notify provider.","wrong":["Documenting without acting allows further hemodynamic compromise.","Fluid restriction in a burn patient with oliguria worsens shock.","Diuretics are contraindicated — they worsen volume depletion in burn resuscitation."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa4', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"Coughing increases intrathoracic pressure which impairs cerebral venous drainage and dramatically raises ICP — this intervention is contraindicated.","wrong":["HOB at 30° promotes cerebral venous drainage and is standard ICP management.","Mannitol is an osmotic diuretic used to reduce cerebral edema.","Minimizing stimulation reduces ICP spikes — appropriate intervention."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa5', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"In DKA, insulin drives potassium into cells, causing hypokalemia. IV potassium must be replaced and verified adequate before insulin is started to prevent life-threatening arrhythmias.","wrong":["Bicarb is reserved for severe acidosis (pH <6.9) — not routine in DKA management.","Insulin is the definitive treatment but must be held until potassium is ≥3.5 mEq/L.","D5W is used later to prevent hypoglycemia once glucose drops to 200 mg/dL — not immediately."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa6', 'existing-original-bank', NULL, true, 'mcq', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"Sudden severe abdominal pain with rigidity post-bowel surgery is a red flag for anastomotic leak, which can cause peritonitis — a surgical emergency.","wrong":["Passage of flatus is a positive sign indicating return of bowel function.","Serosanguineous drainage is expected in early post-op wound healing.","Urine output of 35 mL/hr is normal — above the minimum threshold of 30 mL/hr."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'pa7', 'existing-original-bank', NULL, true, 'mcq', 2, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '[2]'::jsonb, '{"correct":"SpO2 of 88% indicates significant hypoxemia — immediate supplemental oxygen is required to prevent respiratory failure.","wrong":["Fever is expected with pneumonia and requires monitoring but is not immediately life-threatening.","Productive yellow sputum is consistent with bacterial pneumonia — expected finding.","RR of 22 is mildly elevated — concerning but not the priority over hypoxemia."]}'::jsonb, NULL, NULL),
  ('diagnostic', 'bt1', 'existing-original-bank', NULL, true, 'bowtie', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '{"left":[0,1],"center":[0],"right":[0,1]}'::jsonb, '{"condition":"Classic acute decompensated HF with fluid volume excess: crackles, edema, dyspnea, tachycardia, low SpO2.","actions":"Furosemide (loop diuretic) reduces preload and fluid overload. High-Fowler''s reduces work of breathing by using gravity to shift fluid away from lungs.","outcomes":"Urine output and weight confirm diuresis is working. SpO2 and RR confirm respiratory status is improving.","wrong":"Ambulation is inappropriate in acute respiratory distress. Increasing fluids worsens volume overload."}'::jsonb, NULL, NULL),
  ('diagnostic', 'bt2', 'existing-original-bank', NULL, true, 'bowtie', 3, 'Safe & Effective Care Environment', 'Safety & Infection Prevention', 'Safety & Infection Prevention', NULL, NULL, '[]'::jsonb, '{"left":[0,2],"center":[0],"right":[0,1]}'::jsonb, '{"condition":"BP 102/64 with dizziness on standing confirms orthostatic hypotension — a known side effect of amlodipine and hydrochlorothiazide, creating significant fall risk.","actions":"Slow position changes prevent sudden pressure drops. Reviewing antihypertensives with the provider addresses the root pharmacological cause.","outcomes":"Monitoring BP with position changes tracks whether orthostasis resolves. Tracking fall incidents is the primary safety outcome.","wrong":"Compression stockings address DVT, not orthostatic hypotension. Encouraging sodium is not a nursing-scope intervention for this client."}'::jsonb, NULL, NULL),
  ('diagnostic', 'cs1', 'existing-original-bank', NULL, true, 'casestudy', 3, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, NULL, NULL, NULL, 3),
  ('diagnostic', 'cs1:cs1a', 'existing-original-bank', 'cs1', false, 'sata', 3, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[0,2]'::jsonb, '"Glucose of 38 mg/dL is critically low — immediate intervention required. Fever, hypotension, tachycardia, and altered mental status meet SIRS/sepsis criteria. Both are immediate life threats."'::jsonb, 1, NULL),
  ('diagnostic', 'cs1:cs1b', 'existing-original-bank', 'cs1', false, 'mcq', 3, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '"After D50 administration, rechecking glucose in 15 minutes confirms treatment efficacy and guides whether repeat dosing is needed."'::jsonb, 2, NULL),
  ('diagnostic', 'cs1:cs1c', 'existing-original-bank', 'cs1', false, 'mcq', 3, 'Safe & Effective Care Environment', 'Management of Care', 'Management of Care', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '"In suspected sepsis, blood cultures MUST be drawn before IV fluids or antibiotics to prevent contaminating culture results and ensure accurate identification of the organism."'::jsonb, 3, NULL),
  ('diagnostic', 'cs2', 'existing-original-bank', NULL, true, 'casestudy', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, NULL, NULL, NULL, 3),
