  ('diagnostic', 'cs2:cs2b', 'existing-original-bank', 'cs2', false, 'mcq', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '[1]'::jsonb, '"Nitroglycerin causes vasodilation and can severely worsen hypotension. A BP of 88/54 is a contraindication — the provider must be notified before administration."'::jsonb, 2, NULL),
  ('diagnostic', 'cs2:cs2c', 'existing-original-bank', 'cs2', false, 'sata', 3, 'Physiological Integrity', 'Physiological Adaptation', 'Physiological Adaptation', NULL, NULL, '[]'::jsonb, '[0,1,2,4]'::jsonb, '"Aspirin (antiplatelet), oxygen (treat hypoxemia), emergent PCI (reperfusion therapy), and morphine (reduce oxygen demand/pain) are all appropriate for STEMI management. Ambulation is contraindicated in acute STEMI. Fluid restriction is not appropriate — this client may need volume support given hypotension."'::jsonb, 3, NULL),
