  parent_item_id = EXCLUDED.parent_item_id,
  selectable = EXCLUDED.selectable,
  item_type = EXCLUDED.item_type,
  difficulty = EXCLUDED.difficulty,
  blueprint = EXCLUDED.blueprint,
  category = EXCLUDED.category,
  nclex_category = EXCLUDED.nclex_category,
  topic = EXCLUDED.topic,
  cognitive_level = EXCLUDED.cognitive_level,
  core_tags = EXCLUDED.core_tags,
  correct_response = EXCLUDED.correct_response,
  rationale = EXCLUDED.rationale,
  sequence_order = EXCLUDED.sequence_order,
  case_length = EXCLUDED.case_length;

-- Clients must submit answers through the server scorer, not these legacy
-- RPCs, which accept client-supplied correctness and ability values.
ALTER TABLE public.in_house_assessment_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.in_house_assessment_item_responses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "admins manage in-house assessment attempts"
  ON public.in_house_assessment_attempts;
CREATE POLICY "admins manage in-house assessment attempts"
  ON public.in_house_assessment_attempts FOR ALL TO authenticated
  USING (public.is_app_admin()) WITH CHECK (public.is_app_admin());
DROP POLICY IF EXISTS "students read own in-house assessment attempts"
  ON public.in_house_assessment_attempts;
DROP POLICY IF EXISTS "students create own in-house assessment attempts"
  ON public.in_house_assessment_attempts;
REVOKE ALL ON public.in_house_assessment_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.in_house_assessment_attempts TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.in_house_assessment_attempts TO service_role;
REVOKE ALL ON public.in_house_assessment_item_responses FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.save_in_house_assessment_attempt(
  uuid, text, text, text, text, text, text, numeric, integer, integer, timestamptz, jsonb
) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.create_in_house_assessment_attempt(
  uuid, text, text, text, text, integer, boolean, jsonb
) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.checkpoint_in_house_assessment_attempt(
  uuid, integer, jsonb
) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.record_in_house_assessment_response(
  uuid, integer, jsonb, jsonb, numeric
) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.resume_in_house_assessment_attempt(
  uuid, text
) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.abandon_in_house_assessment_attempt(uuid)
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.finalize_in_house_assessment_attempt(
  uuid, text, numeric
) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.commit_in_house_diagnostic_answer(
  p_attempt_id uuid,
  p_expected_revision integer,
  p_responses jsonb,
  p_checkpoint jsonb,
  p_ability_estimate numeric,
  p_result text,
  p_complete boolean
)
RETURNS TABLE (
  checkpoint_revision integer,
  total_questions integer,
  correct_questions integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, auth
AS $$
DECLARE
  v_attempt public.in_house_assessment_attempts;
  v_total integer;
  v_correct integer;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Server assessment access is required';
  END IF;
  IF p_responses IS NULL OR jsonb_typeof(p_responses) <> 'array'
     OR jsonb_array_length(p_responses) = 0 THEN
    RAISE EXCEPTION 'At least one scored response is required';
  END IF;
  IF p_checkpoint IS NULL OR jsonb_typeof(p_checkpoint) <> 'object' THEN
    RAISE EXCEPTION 'Checkpoint must be an object';
  END IF;
  IF p_ability_estimate IS NULL OR p_ability_estimate < 0 OR p_ability_estimate > 1 THEN
    RAISE EXCEPTION 'Ability estimate is invalid';
  END IF;
  IF p_result IS NOT NULL AND p_result NOT IN ('PASS', 'FAIL') THEN
    RAISE EXCEPTION 'Assessment result is invalid';
  END IF;

  SELECT * INTO v_attempt
  FROM public.in_house_assessment_attempts
  WHERE id = p_attempt_id
    AND status = 'in_progress'
    AND checkpoint_revision = p_expected_revision
  FOR UPDATE;
  IF v_attempt.id IS NULL THEN
    RAISE EXCEPTION 'Assessment response conflict or attempt is no longer active';
  END IF;

  INSERT INTO public.in_house_assessment_item_responses (
    attempt_id, item_id, item_source, blueprint, nclex_category, system, topic,
    cognitive_level, difficulty, question_type, selected_answer, correct_answer,
    is_correct, answered_at
  )
  SELECT
    p_attempt_id, response.item_id,
    COALESCE(NULLIF(response.item_source, ''), 'existing-original-bank'),
    response.blueprint, response.nclex_category, response.system, response.topic,
    response.cognitive_level, response.difficulty, response.question_type,
    response.selected_answer, response.correct_answer, response.is_correct,
    COALESCE(response.answered_at, now())
  FROM jsonb_to_recordset(p_responses) AS response(
    item_id text, item_source text, blueprint text, nclex_category text,
    system text, topic text, cognitive_level text, difficulty integer,
    question_type text, selected_answer jsonb, correct_answer jsonb,
    is_correct boolean, answered_at timestamptz
  );

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE is_correct)::integer
  INTO v_total, v_correct
  FROM public.in_house_assessment_item_responses
  WHERE attempt_id = p_attempt_id;

  UPDATE public.in_house_assessment_attempts
  SET ability_estimate = p_ability_estimate,
      total_questions = v_total,
      correct_questions = v_correct,
      checkpoint = p_checkpoint,
      checkpoint_revision = p_expected_revision + 1,
      status = CASE WHEN p_complete THEN 'completed' ELSE 'in_progress' END,
      result = p_result,
      completed_at = CASE WHEN p_complete THEN now() ELSE NULL END,
      updated_at = now()
  WHERE id = p_attempt_id;

  RETURN QUERY SELECT p_expected_revision + 1, v_total, v_correct;
END;
$$;

ALTER FUNCTION public.commit_in_house_diagnostic_answer(
  uuid, integer, jsonb, jsonb, numeric, text, boolean
) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.commit_in_house_diagnostic_answer(
  uuid, integer, jsonb, jsonb, numeric, text, boolean
) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.commit_in_house_diagnostic_answer(
  uuid, integer, jsonb, jsonb, numeric, text, boolean
) TO service_role;

COMMIT;
